function avatar(url?:string){ return url || fallbackAvatar; }

function Toast({message,onClose}:{message:string;onClose:()=>void}){
  useEffect(()=>{const id=setTimeout(onClose,2600);return()=>clearTimeout(id)},[onClose]);
  return <div className="toast" role="status"><CheckCircle2 size={18}/>{message}</div>;
}

function Shell({children}:{children:ReactNode}){
  const {user,logout,schools,defaultScope,refresh}=useAuth(); const [menu,setMenu]=useState(false),[unread,setUnread]=useState(0),[switchingCampus,setSwitchingCampus]=useState(false),[achievements,setAchievements]=useState<Achievement[]>([]); const location=useLocation();
  const fallbackSchool=schools.find(s=>s.id===defaultScope?.schoolId),fallbackCampus=fallbackSchool?.campuses.find(c=>c.id===defaultScope?.campusId),scopeName=user?`${user.schoolName} · ${user.campusName}`:`${fallbackSchool?.name||'校园'} · ${fallbackCampus?.name||'校区'}`;
  const currentSchool=schools.find(s=>s.id===user?.schoolId);
  const switchCampus=async(campusId:string)=>{if(!user||campusId===user.campusId)return;setSwitchingCampus(true);try{await api('/api/me/profile',{method:'PUT',body:JSON.stringify({nickname:user.nickname,wechatId:user.wechatId,campusId,emailMessageNotifications:user.emailMessageNotifications})});await refresh()}catch(error){window.alert(error instanceof Error?error.message:'校区切换失败，请稍后再试')}finally{setSwitchingCampus(false)}};
  useEffect(()=>setMenu(false),[location.pathname]);
  useEffect(()=>{if(!user){setUnread(0);return}const refresh=()=>void api<{count:number}>('/api/conversations/unread-count').then(d=>setUnread(d.count)).catch(()=>{});refresh();const timer=setInterval(refresh,10_000);window.addEventListener('campus-unread-changed',refresh);return()=>{clearInterval(timer);window.removeEventListener('campus-unread-changed',refresh)}},[user?.id]);
  useEffect(()=>{if(!user){setAchievements([]);return}api<{achievements:Achievement[]}>('/api/me/achievements').then(d=>setAchievements(d.achievements)).catch(()=>{})},[user?.id]);
  const lungmen=achievements.find(a=>a.code==='lungmen')?.value??0,originium=achievements.find(a=>a.code==='originium')?.value??0,topAchievements=achievements.filter(a=>a.value===undefined).slice(0,3);
  return <div className="app-shell">
    <header className="site-header"><div className="header-inner">
      <Link to="/" className="brand" aria-label="校园闲置首页"><span className="brand-mark">集</span><span><b>校园闲置</b><small>同校好物 · 当面流转</small></span></Link>
      <nav className="desktop-nav" aria-label="主要导航">
        <NavLink to="/" end><Home/>首页</NavLink><NavLink to="/publish"><Plus/>发布</NavLink><NavLink to="/messages"><span className="nav-icon-badge"><MessageCircle/>{unread>0&&<i>{unread>99?'99+':unread}</i>}</span>消息</NavLink><NavLink to="/feedback"><LifeBuoy/>反馈</NavLink><NavLink to="/mine"><CircleUserRound/>我的</NavLink>
      </nav>
      <div className="header-actions">{user&&currentSchool?.campuses.length?<div className="campus-switcher-stack"><label className={`campus-switcher${switchingCampus?' busy':''}`} title="学校由校园邮箱确定、不可自行修改；校区代表你当前所在/浏览的位置，可随时切换。例如：在中关村校区军训的苏州校区学生，应切换到「中关村校区」。"><MapPin className="campus-pin"/><span className="campus-school">{user.schoolName}<Lock className="campus-lock" aria-hidden="true"/></span><span className="campus-sep">·</span><strong>{user.campusName}</strong><ChevronsUpDown className="switch-cue" aria-hidden="true"/><select value={user.campusId} onChange={e=>void switchCampus(e.target.value)} disabled={switchingCampus} aria-label="切换校区">{currentSchool.campuses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><small className="campus-hint">学校固定 · 校区为当前位置，可切换</small></div>:<span className="school-chip">{scopeName}</span>}{user&&<><Link className="wallet-chip" to="/wallet" title="创世结晶"><i>✨</i>{originium}</Link><Link className="wallet-chip" to="/wallet" title="原石"><i>💎</i>{lungmen}</Link></>}{user?<Link className="user-chip" to="/mine"><img src={avatar(user.avatarUrl)} alt=""/><span>{user.nickname}</span>{topAchievements.map(a=><span key={a.code} className="ach-dot" style={{background:achColors[a.color]?.bg,color:achColors[a.color]?.fg}} title={a.name}>{a.symbol}</span>)}</Link>:<Link className="button primary compact" to="/login">登录</Link>}<button className="icon-button menu-button" onClick={()=>setMenu(v=>!v)} aria-label="打开菜单"><Menu/></button></div>
    </div>{menu&&<div className="mobile-menu"><Link to="/safety">安全交易指南</Link><Link to="/feedback"><LifeBuoy size={17}/>问题反馈与建议</Link>{user&&<button onClick={()=>void logout()}><LogOut size={17}/>退出登录</button>}</div>}</header>
    {user&&!user.campusVerified&&<div className="campus-warning"><ShieldCheck/><span><b>你不是校园认证用户，当前只能查看。</b><small>只有通过平台已配置学校邮箱验证的账号才能发布、评论、收藏和发送消息。</small></span></div>}
    <main>{children}</main>
    <nav className="bottom-nav" aria-label="手机导航"><NavLink to="/" end><Home/><span>首页</span></NavLink><NavLink to="/publish"><Plus/><span>发布</span></NavLink><NavLink to="/messages"><span className="nav-icon-badge"><MessageCircle/>{unread>0&&<i>{unread>99?'99+':unread}</i>}</span><span>消息</span></NavLink><NavLink to="/mine"><CircleUserRound/><span>我的</span></NavLink></nav>
  </div>
}

function RequireAuth({children}:{children:ReactNode}){
  const {user,loading}=useAuth(); const location=useLocation();
  if(loading) return <PageLoading/>; if(!user) return <Navigate to={`/login?next=${encodeURIComponent(location.pathname)}`} replace/>; return children;
}
function RequireCampus({children}:{children:ReactNode}){
  const {user}=useAuth();
  if(!user?.campusVerified)return <div className="campus-blocked"><ShieldCheck/><span className="eyebrow">CAMPUS ONLY</span><h1>你不是校园认证用户</h1><p>当前账号只能查看校园好物。请使用平台已支持学校的校园邮箱注册并完成验证。</p><Link className="button secondary" to="/">返回首页</Link></div>;
  return children;
}
function PageLoading(){return <div className="page-loading"><span></span><p>正在加载校园好物…</p></div>}
function ErrorState({message,retry}:{message:string;retry?:()=>void}){return <div className="empty-state"><span className="empty-icon">!</span><h2>暂时没能加载</h2><p>{message}</p>{retry&&<button className="button secondary" onClick={retry}>重新加载</button>}</div>}

function ItemCard({item,attribution}:{item:Item;attribution?:Attribution}){
  const ref=useRef<HTMLAnchorElement>(null),seen=useRef(false);
  useEffect(()=>{if(!attribution||!ref.current)return;const observer=new IntersectionObserver(entries=>{if(!seen.current&&entries.some(entry=>entry.isIntersecting&&entry.intersectionRatio>=0.5)){seen.current=true;track('item_impression',attribution,{itemId:item.id});observer.disconnect()}},{threshold:0.5});observer.observe(ref.current);return()=>observer.disconnect()},[attribution?.requestId,item.id]);
  return <Link ref={ref} className={`item-card${item.kind==='贴图'?' pic':''}`} to={`/items/${item.id}`} onClick={()=>{if(attribution){saveAttribution(item.id,attribution);track('item_click',attribution,{itemId:item.id})}}}>
    <div className="item-image-wrap"><img src={item.images[0] || 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=800&q=75'} alt={item.title}/><span className="condition-pill">{item.condition}</span>{item.kind==='贴图'&&<span className="kind-pill">贴图</span>}{item.easterEgg&&<span className="egg-pill" role="button" onClick={e=>{e.preventDefault();e.stopPropagation();window.open(easterEggUrls[item.easterEgg!]||'/cat.html','_blank');}}>🐱 猫彩蛋</span>}</div>
    <div className="item-card-body"><h3>{item.title}</h3><p className="item-meta-line"><span>{item.category}</span><time dateTime={item.createdAt}>发布于 {formatTimestamp(item.createdAt)}</time></p><div><strong className={item.kind==='贴图'?'pic-price':''}>{item.kind==='贴图'?item.price:formatItemPrices(item)}</strong></div></div>
  </Link>;
}

function CampusGroupedItems({items}:{items:Item[]}){
  const groups=Array.from(items.reduce((map,item)=>{const key=`${item.schoolId}:${item.campusId}`,group=map.get(key)||{label:`${item.schoolName} · ${item.campusName}`,items:[] as Item[]};group.items.push(item);map.set(key,group);return map},new Map<string,{label:string;items:Item[]}>()).values());
  return <div className="campus-item-groups">{groups.map(group=><section key={group.label}><div className="section-head"><div><span className="eyebrow">CAMPUS</span><h2>{group.label}</h2><p>共 {group.items.length} 件商品</p></div></div><div className="item-grid">{group.items.map(item=><ItemCard key={item.id} item={item}/>)}</div></section>)}</div>;
}

function HomePage(){
  const {user,schools,defaultScope}=useAuth();
  const school=schools.find(s=>s.id===(user?.schoolId||defaultScope?.schoolId)),campus=school?.campuses.find(c=>c.id===(user?.campusId||defaultScope?.campusId)),scopeName=`${user?.schoolName||school?.name||'校园'}${user?.campusName||campus?.name||''}`;
  const [params,setParams]=useSearchParams();
  const [items,setItems]=useState<Item[]>([]);
  const [total,setTotal]=useState(0);
  const [pageSize,setPageSize]=useState(20);
  const [hasMore,setHasMore]=useState(false);
  const [requestId,setRequestId]=useState('');
  const [algorithmVersion,setAlgorithmVersion]=useState('latest-v1');
  const [nextCursor,setNextCursor]=useState<string|null>(null);
  const [previousCursor,setPreviousCursor]=useState<string|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState('');
  const [attempt,setAttempt]=useState(0);
  const pendingSearch=useRef<string|null>(null);
  const keyword=params.get('keyword')||''; const category=params.get('category')||''; const sort=params.get('sort')||'latest';const cursor=params.get('cursor')||'';const regionParam=params.get('region')||'';const isRecommendation=!keyword&&!category&&!regionParam&&sort==='latest';
  const page=Math.max(1,Number.parseInt(params.get('page')||'1',10)||1);
  const [search,setSearch]=useState(keyword);
  useEffect(()=>setSearch(keyword),[keyword]);
  useEffect(()=>{
    const controller=new AbortController();
    setLoading(true);setError('');
    const q=new URLSearchParams({schoolId:user?.schoolId||defaultScope?.schoolId||'',campusId:user?.campusId||defaultScope?.campusId||''});
    if(isRecommendation){q.set('sessionId',analyticsSessionId());if(cursor)q.set('cursor',cursor)}else{q.set('sort',sort);q.set('page',String(page))}
    if(keyword)q.set('keyword',keyword);
    if(category)q.set('category',category);
    api<{items:Item[];total?:number;page?:number;pageSize?:number;hasMore:boolean;requestId:string;algorithmVersion:string;nextCursor?:string|null;previousCursor?:string|null}>(`${isRecommendation?'/api/recommendations':'/api/items'}?${q}`,{signal:controller.signal})
      .then(d=>{setItems(d.items);setTotal(d.total??d.items.length);setPageSize(d.pageSize??20);setHasMore(d.hasMore);setRequestId(d.requestId);setAlgorithmVersion(d.algorithmVersion);setNextCursor(d.nextCursor??null);setPreviousCursor(d.previousCursor??null);if(keyword&&pendingSearch.current===keyword){pendingSearch.current=null;track('search_submit',{requestId:d.requestId,algorithmVersion:d.algorithmVersion,source:'search',position:1},{query:keyword})}})
      .catch(e=>{if(controller.signal.aborted)return;setError(e instanceof Error?e.message:'加载失败')})
      .finally(()=>{if(!controller.signal.aborted)setLoading(false)});
    return ()=>controller.abort();
  },[keyword,category,sort,page,cursor,isRecommendation,attempt,user?.schoolId,user?.campusId,defaultScope?.schoolId,defaultScope?.campusId]);
  const submit=(e:FormEvent)=>{e.preventDefault();const value=search.trim();pendingSearch.current=value||null;const next=new URLSearchParams(params);value?next.set('keyword',value):next.delete('keyword');next.delete('page');next.delete('cursor');setParams(next)};
  const chooseCategory=(name:string)=>{const n=new URLSearchParams(params);category===name?n.delete('category'):n.set('category',name);n.delete('page');n.delete('cursor');setParams(n)};
  const changeSort=(value:string)=>{const n=new URLSearchParams(params);n.set('sort',value);n.delete('page');n.delete('cursor');setParams(n)};
  const gotoPage=(p:number,nextPageCursor?:string|null)=>{if(p<1)return;const n=new URLSearchParams(params);n.set('page',String(p));if(isRecommendation){nextPageCursor?n.set('cursor',nextPageCursor):n.delete('cursor')}setParams(n)};
  const lastPage=Math.max(1,Math.ceil(total/pageSize));
  return <>
    <section className="hero"><div className="hero-inner"><div><span className="eyebrow">CAMPUS MARKET</span><h1>让闲置，在校园里<br/><em>继续被喜欢。</em></h1><p>{scopeName} · 只看同校区真实好物，聊好细节，再当面交易。</p></div><div className="hero-art" aria-hidden="true"><div className="art-card one"><BookOpen/><span>教材笔记</span><b>¥28</b></div><div className="art-card two"><Laptop/><span>数码好物</span><b>¥168</b></div><span className="art-orbit">同校<br/>面交</span></div></div></section>
    <section className="market-container">
      <form className="search-bar" onSubmit={submit}><Search/><input value={search} onChange={e=>setSearch(e.target.value)} maxLength={40} placeholder="搜索教材、数码或宿舍好物" aria-label="搜索商品"/><button>搜索</button></form>
      <div className="category-strip">{categories.map(({name,icon:Icon,tone})=><button key={name} className={`category-button ${category===name?'active':''}`} onClick={()=>chooseCategory(name)}><span className={tone}><Icon/></span>{name}</button>)}</div>
      <Link className="safety-banner" to="/safety"><ShieldCheck/><span><b>校内限定 · 当面验货再交易</b><small>不提前支付押金，不点击陌生付款链接</small></span><ChevronRight/></Link>
      <div className="section-head"><div><span className="eyebrow">{isRecommendation?'FOR YOU':'JUST IN'}</span><h2>{keyword?`“${keyword}”的搜索结果`:category||(isRecommendation?'为你推荐':'本校区好物')}</h2><p>{isRecommendation?'结合新鲜度、热度与多样性，可随时回退最新发布':keyword||category?`共找到 ${total} 件相关好物`:`${scopeName}同学正在转让 · 共 ${total} 件`}</p></div><label className="sort-select"><SlidersHorizontal/><select value={sort} onChange={e=>changeSort(e.target.value)}><option value="latest">{isRecommendation?'智能推荐':'最新发布'}</option><option value="priceAsc">价格从低到高</option><option value="priceDesc">价格从高到低</option></select></label></div>
      {loading?<div className="item-grid skeleton-grid">{[1,2,3,4].map(n=><div key={n} className="skeleton-card"/>)}</div>:error?<ErrorState message={error} retry={()=>setAttempt(a=>a+1)}/>:items.length?<div className="item-grid">{items.map((item,index)=><ItemCard key={item.id} item={item} attribution={{requestId,algorithmVersion,source:keyword?'search':'home',position:(page-1)*pageSize+index+1}}/>)}</div>:<div className="empty-state"><span className="empty-icon">空</span><h2>这里还很安静</h2><p>换个关键词，或者返回上一页看看。</p><Link className="button primary" to="/publish">去发布</Link></div>}
      {!loading&&!error&&total>0&&<nav className="pagination" aria-label="分页导航">
        <button className="pagination-button" type="button" disabled={isRecommendation?!previousCursor:page<=1} onClick={()=>gotoPage(page-1,previousCursor)}><ChevronLeft/>上一页</button>
        <span className="pagination-info">{isRecommendation?`第 ${page} 页`:`第 ${page} / ${lastPage} 页 · 共 ${total} 件`}</span>
        <button className="pagination-button" type="button" disabled={!hasMore} onClick={()=>gotoPage(page+1,nextCursor)}>下一页<ChevronRight/></button>
      </nav>}
    </section>
  </>;
}

function LoginPage(){
  const {user,refresh,emailConfigured,schools,defaultScope}=useAuth(); const navigate=useNavigate(); const [params]=useSearchParams(); const [mode,setMode]=useState<'login'|'register'>('login'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [nickname,setNickname]=useState(''); const [code,setCode]=useState(''); const [campusId,setCampusId]=useState('');const [emailMessageNotifications,setEmailMessageNotifications]=useState(true);const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const [codeBusy,setCodeBusy]=useState(false); const [codeSent,setCodeSent]=useState(false);
  const emailDomain=email.trim().toLowerCase().split('@')[1]||'',matchedSchool=schools.find(s=>s.emailDomains.some(d=>emailDomain===d)),selectedSchool=matchedSchool||schools.find(s=>s.id===defaultScope?.schoolId);
  useEffect(()=>{if(selectedSchool&&!selectedSchool.campuses.some(c=>c.id===campusId))setCampusId(selectedSchool.campuses[0]?.id||'')},[selectedSchool?.id,campusId]);
  if(user) return <Navigate to={params.get('next')||'/'} replace/>;
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await post(`/api/auth/${mode}`,{email,password,nickname,code,campusId,emailMessageNotifications});await refresh();navigate(mode==='register'?'/profile/school-application':params.get('next')||'/');}catch(e){setError(e instanceof Error?e.message:'登录失败')}finally{setBusy(false)}};
  const sendCode=async()=>{setCodeBusy(true);setError('');try{await post('/api/auth/email-code',{email});setCodeSent(true)}catch(e){setError(e instanceof Error?e.message:'验证码发送失败')}finally{setCodeBusy(false)}};
  return <div className="auth-page"><div className="auth-visual"><Link to="/" className="brand light"><span className="brand-mark">集</span><span><b>校园闲置</b><small>同校好物 · 当面流转</small></span></Link><div><span className="eyebrow light">WELCOME BACK</span><h1>好物还在等你，<br/>同学也在。</h1><p>登录后发布闲置、收藏商品，与同校同学放心沟通。</p></div><div className="auth-proof"><ShieldCheck/><span><b>隐私与安全优先</b><small>邮箱验证码短时有效，密码只保存不可逆哈希。</small></span></div></div>
    <div className="auth-panel"><Link to="/" className="close-link" aria-label="返回首页"><X/></Link><div className="auth-card"><span className="eyebrow">CAMPUS ID</span><h2>{mode==='login'?'欢迎回来':'加入校园圈'}</h2><p>{selectedSchool?.name||'多学校校园闲置平台'}</p>
      {error&&<div className="form-error" role="alert">{error}</div>}
      {mode==='register'&&<div className="campus-register-note"><ShieldCheck/><span><b>校园权限说明</b><small>学校由已验证校园邮箱自动确定，注册后普通用户不能自行更改；校区可在个人资料中随时切换。其他邮箱只能浏览。</small></span></div>}
      <form onSubmit={submit}><label>邮箱地址<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="校园邮箱" required autoComplete="email"/></label>{mode==='register'&&<><label>学校<input value={matchedSchool?.name||'未匹配到支持的学校（注册后仅浏览）'} readOnly aria-readonly="true"/></label><label>校区<select value={campusId} onChange={e=>setCampusId(e.target.value)} required>{selectedSchool?.campuses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>校园昵称<input value={nickname} onChange={e=>setNickname(e.target.value)} placeholder="同学们会看到这个名字" minLength={2} maxLength={24} required/></label><label>邮箱验证码<span className="code-field"><input inputMode="numeric" value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6 位验证码" minLength={6} maxLength={6} required/><button type="button" onClick={()=>void sendCode()} disabled={codeBusy||!emailConfigured}>{codeBusy?'发送中':codeSent?'重新发送':'获取验证码'}</button></span></label><label className="notification-setting register-notification"><input type="checkbox" checked={emailMessageNotifications} onChange={e=>setEmailMessageNotifications(e.target.checked)}/><span><b>接收新消息邮件提醒</b><small>仅当你超过 10 分钟未访问平台时发送，可随时在个人资料中关闭。</small></span></label></>}<label>密码<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="至少 8 个字符" minLength={8} maxLength={72} required autoComplete={mode==='login'?'current-password':'new-password'}/></label><button className="button primary wide" disabled={busy}>{busy?'请稍候…':mode==='login'?'邮箱登录':'创建账号并登录'}</button></form>
      <p className="auth-switch">{mode==='login'?'第一次来校园闲置？':'已经有账号？'}<button onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'创建邮箱账号':'返回登录'}</button></p>
      {mode==='login'&&<p className="auth-switch"><Link to="/reset-password">忘记密码？</Link></p>}
    </div></div></div>;
}

function ItemDetailPage(){
  const {id}=useParams(),{user}=useAuth(),navigate=useNavigate(); const [item,setItem]=useState<Item|null>(null),[comments,setComments]=useState<Comment[]>([]),[favorited,setFavorited]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[comment,setComment]=useState(''),[toast,setToast]=useState(''),[reportOpen,setReportOpen]=useState(false),[reportReason,setReportReason]=useState(''),[reportDetail,setReportDetail]=useState(''),[reportBusy,setReportBusy]=useState(false);
  const load=()=>{setLoading(true);api<{item:Item;comments:Comment[];favorited:boolean}>(`/api/items/${id}`).then(d=>{setItem(d.item);setComments(d.comments);setFavorited(d.favorited)}).catch(e=>setError(e.message)).finally(()=>setLoading(false))};useEffect(load,[id]);
  if(loading)return <PageLoading/>;if(error||!item)return <ErrorState message={error||'商品不存在'} retry={load}/>;
  const mustLogin=()=>{navigate(`/login?next=${encodeURIComponent(`/items/${id}`)}`);return false};
  const mustCampus=()=>{setToast('你不是校园认证用户。请使用平台支持的校园邮箱账号。');return false};
  const attribution=itemAttribution(item.id);
  const toggle=async()=>{if(!user)return mustLogin();if(!user.campusVerified)return mustCampus();const d=await post<{favorited:boolean}>(`/api/items/${id}/favorite`,{requestId:attribution.requestId,sessionId:analyticsSessionId(),algorithmVersion:attribution.algorithmVersion});setFavorited(d.favorited);setToast(d.favorited?'已加入收藏':'已取消收藏')};
  const chat=async()=>{if(!user)return mustLogin();if(!user.campusVerified)return mustCampus();try{const d=await post<{id:number}>('/api/conversations',{itemId:item.id,requestId:attribution.requestId,sessionId:analyticsSessionId(),algorithmVersion:attribution.algorithmVersion});navigate(`/messages/${d.id}`)}catch(e){setToast(e instanceof Error?e.message:'无法发起会话')}};
  const sendComment=async()=>{if(!user)return mustLogin();if(!user.campusVerified)return mustCampus();if(comment.trim().length<2)return;await post(`/api/items/${id}/comments`,{content:comment});setComment('');load()};
  const submitReport=async()=>{if(!user)return mustLogin();setReportBusy(true);try{await post('/api/reports',{itemId:item.id,reason:reportReason,detail:reportDetail});setReportOpen(false);setReportReason('');setReportDetail('');setToast('举报已提交，感谢你的反馈')}catch(e){setToast(e instanceof Error?e.message:'举报提交失败')}finally{setReportBusy(false)}};
  const mine=user?.id===item.userId;
  return <div className="detail-container"><Link className="back-link" to="/"><ArrowLeft/>返回好物列表</Link><div className="detail-layout">
    <section className="detail-gallery"><div className="main-photo"><img src={item.images[0]||''} alt={item.title}/><span>{item.status}</span></div>{item.images.length>1&&<div className="thumb-row">{item.images.map((src,n)=><img key={src} src={src} alt={`${item.title} 图片 ${n+1}`}/>)}</div>}</section>
    <section className="detail-summary"><div className="price-time"><strong><small>¥</small>{item.price}</strong><time dateTime={item.createdAt}>发布于 {formatTimestamp(item.createdAt)}</time></div><h1>{item.title}</h1><div className="tag-row"><span>{item.category}</span><span>{item.condition}</span><span>{item.campusName}面交</span></div><Link className="seller-box" to={`/users/${item.userId}`} aria-label={`查看 ${item.seller?.nickname||'卖家'} 的主页`}><img src={avatar(item.seller?.avatarUrl)} alt=""/><span><b>{item.seller?.nickname||'校园同学'} {item.seller?.verified&&<i>已认证</i>}</b><small>{item.schoolName} · {item.campusName} · 查看主页</small></span><ChevronRight/></Link><div className="detail-actions">{mine?<Link className="button primary wide" to={`/items/${id}/edit`}><Edit3/>编辑商品</Link>:<><button className="button secondary favorite-button" onClick={()=>void toggle()}><Heart fill={favorited?'currentColor':'none'}/>{favorited?'已收藏':'收藏'}</button><button className="button primary" onClick={()=>void chat()}><MessageCircle/>我想要</button><button className="report-link" onClick={()=>setReportOpen(true)}>举报</button></>}</div></section>
  </div><div className="detail-content-grid"><section className="content-card"><span className="eyebrow">DETAILS</span><h2>商品信息</h2><div className="spec-grid"><span><small>分类</small><b>{item.category}</b></span><span><small>成色</small><b>{item.condition}</b></span><span><small>交易方式</small><b>校内面交</b></span></div><h3>详细描述</h3><p className="description-text">{item.description||'卖家暂未补充更多描述，可以发消息进一步沟通。'}</p></section><aside className="safety-card"><ShieldCheck/><h3>当面验货，再确认交易</h3><p>建议在教学楼、食堂等校内公共区域见面。</p><Link to="/safety">查看安全交易指南 <ChevronRight/></Link></aside></div>
  <section className="comments-card"><div className="comment-head"><div><span className="eyebrow">CAMPUS TALK</span><h2>同学评论 <small>{comments.length}</small></h2></div></div>{user&&!user.campusVerified?<div className="inline-campus-lock"><ShieldCheck/><span><b>你不是校园认证用户，不能评论</b><small>评论仅对通过平台已配置学校邮箱验证的账号开放。</small></span></div>:<div className="comment-composer"><img src={avatar(user?.avatarUrl)} alt=""/><textarea value={comment} onChange={e=>setComment(e.target.value)} maxLength={200} placeholder="想了解商品细节？在这里问问卖家和同学"/><button onClick={()=>void sendComment()} disabled={comment.trim().length<2}><Send/></button></div>}<div className="comment-list">{comments.map(c=><article key={c.id}><img src={avatar(c.author.avatarUrl)} alt=""/><div><p><b>{c.author.nickname}</b>{c.author.isSeller&&<span>卖家</span>}<time dateTime={c.createdAt}>{formatTimestamp(c.createdAt)}</time></p><div>{c.content}</div></div></article>)}{!comments.length&&<p className="muted center">还没有评论，来成为第一个提问的同学。</p>}</div></section>{reportOpen&&<div className="report-backdrop" onClick={()=>setReportOpen(false)}><div className="report-modal" onClick={e=>e.stopPropagation()}><div className="report-head"><div><b>举报这件商品</b><small>请选择原因并补充说明，我们会尽快核实处理。</small></div><button onClick={()=>setReportOpen(false)}><X/></button></div><div className="report-reasons">{['虚假信息','违规内容','诈骗风险','重复发布','其他'].map(r=><label key={r} className={reportReason===r?'active':''}><input type="radio" name="report-reason" value={r} checked={reportReason===r} onChange={()=>setReportReason(r)}/><span>{r}</span></label>)}</div><textarea value={reportDetail} onChange={e=>setReportDetail(e.target.value)} maxLength={500} placeholder="补充说明（选填，方便核实）"/><div className="report-actions"><button className="button secondary" onClick={()=>setReportOpen(false)}>取消</button><button className="button primary" disabled={reportBusy||!reportReason} onClick={()=>void submitReport()}>{reportBusy?'提交中…':'提交举报'}</button></div></div></div>}{toast&&<Toast message={toast} onClose={()=>setToast('')}/>}</div>;
}

type ItemForm={title:string;price:string;category:string;condition:string;description:string;images:string[];status:string;campusId:string;currency:'cny'|'lungmen';rmbPrice:string;regions:string[];kind:string};
function PublishPage(){
  const {id}=useParams(),navigate=useNavigate(),{user,schools}=useAuth();const editing=Boolean(id);const currentSchool=schools.find(s=>s.id===user?.schoolId);const [form,setForm]=useState<ItemForm>({title:'',price:'',category:'',condition:'',description:'',images:[],status:'在售',campusId:user?.campusId||'',currency:'cny',rmbPrice:'',regions:[],kind:'商品'}),[busy,setBusy]=useState(false),[uploading,setUploading]=useState(false),[error,setError]=useState('');
  useEffect(()=>{if(editing)api<{item:Item}>(`/api/items/${id}`).then(({item})=>setForm({title:item.title,price:String(item.price),category:item.category,condition:item.condition,description:item.description,images:item.images,status:item.status,campusId:item.campusId,currency:item.currency==='lungmen'?'lungmen':'cny',rmbPrice:item.rmbPrice!=null?String(item.rmbPrice):'',regions:item.regions||[],kind:item.kind||'商品'})).catch(e=>setError(e.message))},[id,editing]);
  useEffect(()=>{if(!form.campusId&&user?.campusId)setForm(f=>({...f,campusId:user.campusId}))},[user?.campusId]);
  const set=<K extends keyof ItemForm>(key:K,value:ItemForm[K])=>setForm(f=>({...f,[key]:value}));
  const toggleRegion=(name:string)=>setForm(f=>({...f,regions:f.regions.includes(name)?f.regions.filter(r=>r!==name):[...f.regions,name]}));
  const upload=async(files:FileList|null)=>{if(!files?.length)return;setUploading(true);setError('');try{const data=new FormData();Array.from(files).slice(0,9-form.images.length).forEach(f=>data.append('images',f));const result=await api<{urls:string[]}>('/api/uploads',{method:'POST',body:data});set('images',[...form.images,...result.urls])}catch(e){setError(e instanceof Error?e.message:'上传失败')}finally{setUploading(false)}};
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(editing){await api(`/api/items/${id}`,{method:'PATCH',body:JSON.stringify(form)});navigate(`/items/${id}`)}else{const d=await post<{id:number}>('/api/items',form);navigate(`/items/${d.id}`)}}catch(e){setError(e instanceof Error?e.message:'发布失败')}finally{setBusy(false)}};
  return <div className="form-page"><div className="page-title"><span className="eyebrow">PASS IT ON</span><h1>{editing?'编辑商品':'让闲置，找到新主人。'}</h1><p>真实一点写，方便同学快速决定。</p></div><form className="publish-form" onSubmit={submit}>{error&&<div className="form-error">{error}</div>}<section><div className="field-heading"><b>商品照片</b><small>第一张会成为封面，最多 9 张</small></div><div className="upload-grid">{form.images.map((src,n)=><div className="upload-preview" key={src}><img src={src} alt={`商品图片 ${n+1}`}/><button type="button" onClick={()=>set('images',form.images.filter((_,i)=>i!==n))}><X/></button></div>)}{form.images.length<9&&<label className="upload-button"><ImagePlus/><span>{uploading?'上传中…':'添加照片'}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple onChange={e=>void upload(e.target.files)} disabled={uploading}/></label>}</div></section><section><div className="field-heading"><b>商品信息</b><small>带 * 为必填项</small></div><label>发布校区 *<select value={form.campusId} onChange={e=>set('campusId',e.target.value)} required>{currentSchool?.campuses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><small>商品将只展示给所选校区的同学。</small></label><div className="two-fields"><label>交易币种 *<select value={form.currency} onChange={e=>set('currency',e.target.value as 'cny'|'lungmen')} required><option value="cny">人民币</option><option value="lungmen">原石</option></select></label><label>发布性质<select value={form.kind} onChange={e=>set('kind',e.target.value)}>{kinds.map(k=><option key={k}>{k}</option>)}</select></label></div>{form.currency==='lungmen'&&<label>人民币参考价（可选）<span className="price-input"><b>¥</b><input inputMode="decimal" value={form.rmbPrice} onChange={e=>set('rmbPrice',e.target.value)} placeholder="0.00"/></span></label>}<label>商品标题 *<input value={form.title} onChange={e=>set('title',e.target.value)} placeholder="例如：九成新蓝牙机械键盘" minLength={3} maxLength={80} required/></label><div className="two-fields"><label>分类 *<select value={form.category} onChange={e=>set('category',e.target.value)} required><option value="">选择分类</option>{categories.map(c=><option key={c.name}>{c.name}</option>)}</select></label><label>成色 *<select value={form.condition} onChange={e=>set('condition',e.target.value)} required><option value="">选择成色</option>{conditions.map(c=><option key={c}>{c}</option>)}</select></label></div><label>价格 *<span className="price-input"><b>{form.currency==='cny'?'¥':'石'}</b><input inputMode="decimal" value={form.price} onChange={e=>set('price',e.target.value)} placeholder={form.currency==='cny'?'0.00':'正整数'} required/></span><small>{form.currency==='cny'?'人民币计价':'原石计价，需为正整数'}</small></label><div className="field-heading"><b>商品区域 *</b><small>至少选择一个区域</small></div><div className="region-picker">{regions.map(r=><label key={r} className={`region-chip${form.regions.includes(r)?' active':''}`}><input type="checkbox" checked={form.regions.includes(r)} onChange={()=>toggleRegion(r)}/><span>{r}</span></label>)}</div><label>详细描述<textarea value={form.description} onChange={e=>set('description',e.target.value)} maxLength={1000} placeholder="说说来源、使用情况和交易偏好吧…"/></label>{editing&&<label>商品状态<select value={form.status} onChange={e=>set('status',e.target.value)}><option>在售</option><option>已售出</option><option>已下架</option></select></label>}</section><button className="button primary wide submit-publish" disabled={busy||uploading}><Upload/>{busy?'保存中…':editing?'保存修改':'发布到校园圈'}</button></form></div>;
}

function MessagesPage(){
  const [list,setList]=useState<Conversation[]>([]),[loading,setLoading]=useState(true);useEffect(()=>{api<{conversations:Conversation[]}>('/api/conversations').then(d=>setList(d.conversations)).finally(()=>setLoading(false))},[]);
  return <div className="narrow-page"><div className="page-title"><span className="eyebrow">KEEP IN TOUCH</span><h1>聊聊好物</h1><p>和同学约个时间，聊聊细节。</p></div>{loading?<PageLoading/>:list.length?<div className="conversation-list">{list.map(c=><Link to={`/messages/${c.id}`} key={c.id}><img src={avatar(c.partner.avatarUrl)} alt=""/><span><b>{c.partner.nickname}</b><small>关于 · {c.itemTitle}</small><p>{c.lastMessage||'发一条消息开始沟通吧'}</p></span>{c.unreadCount>0?<strong className="conversation-unread">{c.unreadCount>99?'99+':c.unreadCount}</strong>:<ChevronRight/>}</Link>)}</div>:<div className="empty-state"><span className="empty-icon"><MessageCircle/></span><h2>还没有对话</h2><p>遇到喜欢的好物，就和 TA 打个招呼吧。</p><Link className="button primary" to="/">去逛逛</Link></div>}</div>;
}

function ChatPage(){
  const {id}=useParams(),{user}=useAuth();const [messages,setMessages]=useState<ChatMessage[]>([]),[title,setTitle]=useState('商品会话'),[text,setText]=useState(''),[emailNotice,setEmailNotice]=useState(''),[error,setError]=useState('');const end=useRef<HTMLDivElement>(null);
  const load=async()=>{try{const d=await api<{conversation:{itemTitle:string};messages:ChatMessage[]}>(`/api/conversations/${id}/messages`);setTitle(d.conversation.itemTitle);setMessages(d.messages);setError('');void post(`/api/conversations/${id}/read`).then(()=>window.dispatchEvent(new Event('campus-unread-changed'))).catch(()=>{})}catch(e){setError(e instanceof Error?e.message:'加载失败')}};
  useEffect(()=>{void load();const timer=setInterval(()=>void load(),3000);return()=>clearInterval(timer)},[id]);useEffect(()=>end.current?.scrollIntoView({behavior:'smooth'}),[messages.length]);
  const send=async(e:FormEvent)=>{e.preventDefault();if(!text.trim())return;const value=text;setText('');try{const result=await post<{emailNotification:'sent'|'recent_online'|'disabled'|'failed'}>(`/api/conversations/${id}/messages`,{content:value});setEmailNotice(result.emailNotification==='sent'?'消息已发送，并已发送邮件提醒':result.emailNotification==='recent_online'?'消息已发送；对方最近在线，未发邮件':result.emailNotification==='disabled'?'消息已发送；对方已关闭邮件提醒':'消息已发送；邮件提醒发送失败');await load()}catch(e){setText(value);setError(e instanceof Error?e.message:'发送失败')}};
  return <div className="chat-page"><div className="chat-head"><Link to="/messages"><ArrowLeft/></Link><div><b>{title}</b><small className={emailNotice?'email-send-status':''}>{emailNotice||'每 3 秒自动刷新'}</small></div></div>{error&&<div className="form-error">{error}</div>}<div className="message-stream">{messages.map(m=><div className={`message-row ${m.mine?'mine':''} ${m.type==='item_card'?'item-card-row':''}`} key={m.id}>{!m.mine&&<img src={avatar(m.sender.avatarUrl)} alt=""/>}<div>{m.type==='item_card'&&m.item?<Link className="chat-item-card" to={`/items/${m.item.id}`}><img src={m.item.image} alt=""/><span><small>从商品进入对话</small><b>{m.item.title}</b><em>{formatItemPrices(m.item)}</em><i>{m.item.condition} · {m.item.status}</i></span><ChevronRight/></Link>:<p>{m.content}</p>}<time dateTime={m.createdAt}>{formatTimestamp(m.createdAt)}</time></div></div>)}<div ref={end}/></div>{user?.campusVerified?<form className="chat-composer" onSubmit={send}><input value={text} onChange={e=>setText(e.target.value)} maxLength={500} placeholder="礼貌沟通，约个安全的见面地点"/><button aria-label="发送消息" disabled={!text.trim()}><Send/></button></form>:<div className="chat-readonly">你不是校园认证用户，当前只能查看消息。</div>}</div>;
}

function ItemCollection({kind}:{kind:'mine'|'favorites'}){
  const [items,setItems]=useState<Item[]>([]),[loading,setLoading]=useState(true);useEffect(()=>{api<{items:Item[]}>(kind==='mine'?'/api/me/items':'/api/me/favorites').then(d=>setItems(d.items)).finally(()=>setLoading(false))},[kind]);
  return <div className="market-container sub-page"><div className="page-title"><span className="eyebrow">{kind==='mine'?'MY LISTINGS':'SAVED'}</span><h1>{kind==='mine'?'我的发布':'我的收藏'}</h1><p>{kind==='mine'?'按发布时的学校与校区分区管理，切换校区不会移动历史商品。':'把感兴趣的同校好物先放在这里。'}</p></div>{loading?<PageLoading/>:items.length?<CampusGroupedItems items={items}/>:<div className="empty-state"><span className="empty-icon">空</span><h2>这里还是空的</h2><Link className="button primary" to={kind==='mine'?'/publish':'/'}>{kind==='mine'?'发布第一件商品':'去逛逛'}</Link></div>}</div>;
}

function UserProfilePage(){
  const {id}=useParams(),[profile,setProfile]=useState<PublicProfile|null>(null),[items,setItems]=useState<Item[]>([]),[allCampuses,setAllCampuses]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const load=()=>{setLoading(true);setError('');api<{profile:PublicProfile;items:Item[];allCampuses:boolean}>(`/api/users/${id}`).then(data=>{setProfile(data.profile);setItems(data.items);setAllCampuses(data.allCampuses)}).catch(e=>setError(e instanceof Error?e.message:'用户主页加载失败')).finally(()=>setLoading(false))};
  useEffect(load,[id]);if(loading)return <PageLoading/>;if(error||!profile)return <div className="market-container sub-page"><ErrorState message={error||'用户不存在'} retry={load}/></div>;
  return <div className="market-container sub-page public-profile-page"><Link className="back-link" to="/"><ArrowLeft/>返回好物列表</Link><section className="public-profile-hero"><img src={avatar(profile.avatarUrl)} alt={`${profile.nickname} 的头像`}/><div><span className={`verified-line ${profile.campusVerified?'':'not-campus'}`}><ShieldCheck/>{profile.campusVerified?'已认证校园账号':'未认证校园身份'}</span><h1>{profile.nickname}</h1><p>{profile.schoolName} · {profile.campusName}</p></div></section><div className="profile-privacy-note"><ShieldCheck/><span><b>隐私保护</b><small>{allCampuses?'这是你自己的主页，按发布校区展示全部状态商品。':'主页仅展示当前校区的在售商品，不公开联系方式或在线状态。'}</small></span></div><div className="section-head public-listing-head"><div><span className="eyebrow">CURRENT LISTINGS</span><h2>{allCampuses?'我的全部商品':'TA 在本校区的在售好物'}</h2><p>共 {items.length} 件</p></div></div>{items.length?<CampusGroupedItems items={items}/>:<div className="empty-state"><span className="empty-icon"><Package/></span><h2>{allCampuses?'还没有发布商品':'当前校区暂无在售商品'}</h2><p>已售出和已下架内容不会在公开主页展示。</p></div>}</div>;
}

function OrdersPage(){
  const [orders,setOrders]=useState<Order[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState('');
  const load=()=>{setLoading(true);setError('');api<{orders:Order[]}>('/api/me/orders').then(d=>setOrders(d.orders)).catch(e=>setError(e instanceof Error?e.message:'加载失败')).finally(()=>setLoading(false))};
  useEffect(load,[]);
  const act=async(order:Order,action:'confirm'|'cancel')=>{if(action==='cancel'&&!window.confirm('确定取消订单？支付的币种将退回你的钱包。'))return;try{await post(`/api/orders/${order.id}/${action}`);load()}catch(e){setError(e instanceof Error?e.message:'操作失败')}};
  const statusLabel=(s:string)=>s==='已完成'?'已完成':s==='已取消'?'已取消':'待确认收货';
  return <div className="market-container sub-page"><div className="page-title"><span className="eyebrow">ORDERS</span><h1>我的订单</h1><p>在线币种支付采用担保交易：确认收货后货款才会打给卖家。</p></div>{loading?<PageLoading/>:error?<ErrorState message={error}/>:orders.length?<div className="conversation-list">{orders.map(o=><div key={o.id} className="order-card"><img src={o.itemImage||fallbackAvatar} alt=""/><span className="order-main"><b>{o.itemTitle}</b><small>{o.role==='buyer'?'卖家':'买家'}：{o.counterpart.nickname} · {formatTimestamp(o.createdAt)}</small><em>{o.amount} {currencyOf(o.currency).name}</em></span><span className="order-side"><i>{statusLabel(o.status)}</i>{o.role==='buyer'&&o.status==='待确认收货'&&<><button className="button primary compact" onClick={()=>void act(o,'confirm')}>确认收货</button><button className="button secondary compact" onClick={()=>void act(o,'cancel')}>取消</button></>}</span></div>)}</div>:<div className="empty-state"><span className="empty-icon"><Package/></span><h2>还没有订单</h2><Link className="button primary" to="/">去逛逛</Link></div>}</div>;
}

function WalletPage(){
  const [wallet,setWallet]=useState<Wallet|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');
  useEffect(()=>{api<Wallet>('/api/me/wallet').then(setWallet).catch(e=>setError(e instanceof Error?e.message:'加载失败')).finally(()=>setLoading(false))},[]);
  return <div className="market-container sub-page"><div className="page-title"><span className="eyebrow">MY WALLET</span><h1>我的钱包</h1><p>查看你获得的原石与创世结晶，以及最近的发放记录。</p></div>{loading?<PageLoading/>:error?<ErrorState message={error}/>:wallet?<><section className="stats-row">{Object.values(wallet.wallet).map(b=><div key={b.code}><b>{b.balance}</b><span>{b.name}</span></div>)}</section><section className="wallet-ledger"><h2>最近发放记录</h2>{wallet.entries.length?<ul>{wallet.entries.map(e=>{const b=wallet.wallet[e.currency];return <li key={e.id}><span><b>{b?b.name:e.currency}</b><small>{formatTimestamp(e.createdAt)} · {e.operator}</small></span><em>{e.amount>0?'+':''}{e.amount}</em><small>{e.reason}</small></li>})}</ul>:<p className="muted center">还没有奖励记录</p>}</section></>:null}</div>;
}

function MinePage(){
  const {user,logout}=useAuth(),navigate=useNavigate();const [stats,setStats]=useState({total:0,selling:0,sold:0}),[achievements,setAchievements]=useState<Achievement[]>([]),[ach,setAch]=useState<Achievement|null>(null);useEffect(()=>{api<{stats:typeof stats}>('/api/me/stats').then(d=>setStats(d.stats))},[]);useEffect(()=>{api<{achievements:Achievement[]}>('/api/me/achievements').then(d=>setAchievements(d.achievements)).catch(()=>{})},[]);if(!user)return null;
  return <div className="profile-page"><section className="profile-hero"><img src={avatar(user.avatarUrl)} alt="个人头像"/><div><span className={`verified-line ${user.campusVerified?'':'not-campus'}`}><ShieldCheck/>{user.campusVerified?'已认证校园账号':'非校园邮箱 · 仅可浏览'}</span><h1>{user.nickname}</h1><p>{user.email} · {user.schoolName} · {user.campusName}</p></div><Link className="button secondary" to="/profile"><Edit3/>编辑资料</Link></section>{achievements.length>0&&<section className="achievements-row">{achievements.map(a=><button key={a.code} type="button" className="ach-badge" style={{background:achColors[a.color]?.bg,color:achColors[a.color]?.fg}} title={a.name} onClick={()=>setAch(a)}><span>{a.symbol}</span>{a.value!==undefined&&<i>{a.value}</i>}</button>)}</section>}<section className="stats-row"><div><b>{stats.total}</b><span>累计发布</span></div><div><b>{stats.selling}</b><span>正在出售</span></div><div><b>{stats.sold}</b><span>已经售出</span></div></section><section className="mine-grid"><Link to="/my-items"><span className="feature-icon blue"><Package/></span><div><b>我的发布</b><small>管理闲置与状态</small></div><ChevronRight/></Link><Link to="/favorites"><span className="feature-icon rose"><Heart/></span><div><b>我的收藏</b><small>查看感兴趣的好物</small></div><ChevronRight/></Link><Link to="/wallet"><span className="feature-icon amber"><Coins/></span><div><b>我的钱包</b><small>查看原石与创世结晶余额</small></div><ChevronRight/></Link><Link to="/messages"><span className="feature-icon green"><MessageCircle/></span><div><b>商品消息</b><small>继续和同学沟通</small></div><ChevronRight/></Link><Link to="/orders"><span className="feature-icon violet"><ShoppingBag/></span><div><b>我的订单</b><small>查看购买与出售的担保交易</small></div><ChevronRight/></Link><Link to="/feedback"><span className="feature-icon blue"><LifeBuoy/></span><div><b>问题反馈与建议</b><small>报告异常或告诉我们你的想法</small></div><ChevronRight/></Link><Link to="/safety"><span className="feature-icon amber"><ShieldCheck/></span><div><b>安全交易指南</b><small>校内面交与防骗提醒</small></div><ChevronRight/></Link><Link to="/password"><span className="feature-icon violet"><ShieldCheck/></span><div><b>账号安全</b><small>修改登录密码</small></div><ChevronRight/></Link>{user.role==='admin'&&<Link to="/admin"><span className="feature-icon violet"><ShieldCheck/></span><div><b>管理后台</b><small>管理用户、商品与举报</small></div><ChevronRight/></Link>}</section><button className="logout-button" onClick={async()=>{await logout();navigate('/')}}><LogOut/>退出登录</button>{ach&&<div className="report-backdrop" onClick={()=>setAch(null)}><div className="report-modal" onClick={e=>e.stopPropagation()}><div className="report-head"><div><b>{ach.symbol} {ach.name}</b><small>成就详情</small></div><button onClick={()=>setAch(null)}><X/></button></div><div className="ach-detail"><p>{ach.description}</p>{ach.value!==undefined&&<p className="ach-value">数量：{ach.value}</p>}</div><div className="report-actions"><button className="button primary" onClick={()=>setAch(null)}>知道了</button></div></div></div>}</div>;
}

function ProfileDetailsPage(){
  const {user,refresh,schools}=useAuth(),navigate=useNavigate();const [nickname,setNickname]=useState(user?.nickname||''),[avatarUrl,setAvatarUrl]=useState(user?.avatarUrl||''),[wechatId,setWechatId]=useState(user?.wechatId||''),[campusId,setCampusId]=useState(user?.campusId||''),[emailMessageNotifications,setEmailMessageNotifications]=useState(user?.emailMessageNotifications!==false),[cropFile,setCropFile]=useState<File|null>(null),[avatarUploading,setAvatarUploading]=useState(false),[avatarDone,setAvatarDone]=useState(false),[error,setError]=useState('');
  const currentSchool=schools.find(s=>s.id===user?.schoolId);
  const uploadAvatar=async(file?:File)=>{if(!file)return;setAvatarUploading(true);setAvatarDone(false);setError('');try{const data=new FormData();data.append('avatar',file);const result=await api<{avatarUrl:string}>('/api/me/avatar',{method:'POST',body:data});setAvatarUrl(result.avatarUrl);setAvatarDone(true);await refresh()}catch(e){setError(e instanceof Error?e.message:'头像上传失败')}finally{setAvatarUploading(false)}};
  const chooseAvatar=(file?:File)=>{if(!file)return;if(file.size>20*1024*1024){setError('原始图片不能超过 20MB');return}setError('');setCropFile(file)};
  const submit=async(e:FormEvent)=>{e.preventDefault();try{await api('/api/me/profile',{method:'PUT',body:JSON.stringify({nickname,wechatId,campusId,emailMessageNotifications})});await refresh();navigate('/mine')}catch(e){setError(e instanceof Error?e.message:'保存失败')}};
  return <><div className="form-page compact-form"><div className="page-title"><span className="eyebrow">PROFILE</span><h1>账号与个人资料</h1><p>联系方式只用于交易沟通，不在商品列表公开。</p></div><form className="publish-form" onSubmit={submit}>{error&&<div className="form-error">{error}</div>}<div className="avatar-editor"><label className="avatar-upload"><img src={avatar(avatarUrl)} alt="头像预览"/><span><ImagePlus/>{avatarUploading?'上传中…':'更换头像'}</span><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>chooseAvatar(e.target.files?.[0])} disabled={avatarUploading}/></label><div><b>{avatarDone?'头像已更新':'上传并裁切头像'}</b><small>支持 JPG、PNG、WebP；大于 2MB 自动压缩</small></div></div><label>学校（认证后不可自行修改）<input value={user?.schoolName||''} readOnly aria-readonly="true"/></label><label>校区<select value={campusId} onChange={e=>setCampusId(e.target.value)} required>{currentSchool?.campuses.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>校园昵称<input value={nickname} onChange={e=>setNickname(e.target.value)} minLength={2} maxLength={24} required/></label><label>微信号（可选）<input value={wechatId} onChange={e=>setWechatId(e.target.value)} maxLength={40} placeholder="仅在你同意时告知交易对象"/></label><label className="notification-setting"><input type="checkbox" checked={emailMessageNotifications} onChange={e=>setEmailMessageNotifications(e.target.checked)}/><span><b>接收新消息邮件提醒</b><small>你最近 10 分钟没有访问平台时，才会发送提醒邮件。</small></span></label><button className="button primary wide">保存资料</button></form><p className="auth-switch"><Link to="/password">修改密码</Link></p></div>{cropFile&&<AvatarCropper file={cropFile} onCancel={()=>setCropFile(null)} onDone={file=>{setCropFile(null);void uploadAvatar(file)}}/>}</>;
}

function ProfilePage(){return <><ProfileDetailsPage/><div className="form-page compact-form"><ScopeApplicationForm/></div></>}

function SchoolApplicationPage(){return <div className="form-page compact-form"><div className="page-title"><span className="eyebrow">CAMPUS REVIEW</span><h1>提交学校与校区申请</h1><p>注册完成后，在这里提交由管理员核验的归属材料。</p></div><ScopeApplicationForm/></div>}

function FeedbackPage(){
  const [type,setType]=useState('问题反馈'),[content,setContent]=useState(''),[busy,setBusy]=useState(false),[sent,setSent]=useState(false),[error,setError]=useState('');
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await post('/api/feedback',{type,content});setSent(true);setContent('')}catch(e){setError(e instanceof Error?e.message:'反馈提交失败')}finally{setBusy(false)}};
  if(sent)return <div className="feedback-page"><div className="feedback-success"><CheckCircle2/><span className="eyebrow">THANK YOU</span><h1>谢谢你的反馈</h1><p>内容已经安全保存，我们会认真查看。需要补充其他信息时，可以再次提交。</p><div><button className="button secondary" onClick={()=>setSent(false)}>继续反馈</button><Link className="button primary" to="/">返回首页</Link></div></div></div>;
  return <div className="feedback-page"><div className="page-title"><span className="eyebrow">HELP US IMPROVE</span><h1>问题反馈与建议</h1><p>遇到异常，或者有更好的想法，都可以告诉我们。</p></div><form className="feedback-form" onSubmit={submit}>{error&&<div className="form-error">{error}</div>}<fieldset><legend>反馈类型</legend><div className="feedback-types">{['问题反馈','功能建议','其他'].map(option=><label className={type===option?'active':''} key={option}><input type="radio" name="feedback-type" value={option} checked={type===option} onChange={()=>setType(option)}/><span>{option}</span></label>)}</div></fieldset><label>详细内容<textarea value={content} onChange={e=>setContent(e.target.value)} minLength={10} maxLength={1000} required placeholder={type==='问题反馈'?'请描述发生了什么、你当时在哪个页面，以及希望看到的结果…':'请详细说说你的想法和使用场景…'}/><small>{content.length}/1000 · 至少 10 个字符</small></label><div className="feedback-privacy"><ShieldCheck/><span><b>隐私说明</b><small>反馈会关联你的账号邮箱，仅用于必要的问题跟进，不会公开展示或提供给其他用户。</small></span></div><button className="button primary wide" disabled={busy||content.trim().length<10}><Send/>{busy?'提交中…':'提交反馈'}</button></form></div>;
}

function SafetyPage(){return <div className="safety-page"><div className="safety-intro"><ShieldCheck/><span className="eyebrow light">TRADE SAFELY</span><h1>校园面交，安全第一。</h1><p>平台只提供信息与沟通服务，请根据实物情况自主判断。</p></div><div className="safety-list"><article><b>01</b><div><h2>优先公共区域见面</h2><p>选择教学楼、食堂、图书馆等人流稳定的校内地点，避免夜间前往偏僻区域。</p></div></article><article><b>02</b><div><h2>当面验货再付款</h2><p>确认型号、功能、配件和实际成色，电子产品建议现场开机测试。</p></div></article><article><b>03</b><div><h2>拒绝押金与陌生链接</h2><p>不要提前支付订金、保证金或运费，不扫描来源不明的收款码。</p></div></article><article><b>04</b><div><h2>保留平台沟通记录</h2><p>重要约定尽量在站内消息中确认，发现异常及时停止交易。</p></div></article></div><Link className="button primary" to="/">我知道了，去逛逛</Link></div>}

function ResetPasswordPage(){
  const {emailConfigured}=useAuth();const [email,setEmail]=useState('');const [code,setCode]=useState('');const [password,setPassword]=useState('');const [codeSent,setCodeSent]=useState(false);const [codeBusy,setCodeBusy]=useState(false);const [busy,setBusy]=useState(false);const [done,setDone]=useState(false);const [error,setError]=useState('');
  const sendCode=async()=>{if(!email)return;setCodeBusy(true);setError('');try{await post('/api/auth/forgot-password',{email});setCodeSent(true)}catch(e){setError(e instanceof Error?e.message:'验证码发送失败')}finally{setCodeBusy(false)}};
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await post('/api/auth/reset-password',{email,code,password});setDone(true)}catch(e){setError(e instanceof Error?e.message:'重置失败')}finally{setBusy(false)}};
  if(done)return <div className="form-page compact-form"><div className="feedback-success"><CheckCircle2/><span className="eyebrow">DONE</span><h1>密码已重置</h1><p>请使用新密码登录。为了账号安全，所有设备上的登录状态已失效。</p><div><Link className="button primary" to="/login">去登录</Link></div></div></div>;
  return <div className="form-page compact-form"><div className="page-title"><span className="eyebrow">RECOVER ACCOUNT</span><h1>重置密码</h1><p>输入注册邮箱获取验证码，验证通过后设置新密码。</p></div><form className="publish-form" onSubmit={submit}>{error&&<div className="form-error" role="alert">{error}</div>}<label>注册邮箱<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="校园邮箱" required autoComplete="email"/></label><label>邮箱验证码<span className="code-field"><input inputMode="numeric" value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6 位验证码" minLength={6} maxLength={6} required/><button type="button" onClick={()=>void sendCode()} disabled={codeBusy||!emailConfigured||!email}>{codeBusy?'发送中':codeSent?'重新发送':'获取验证码'}</button></span></label><label>新密码<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="至少 8 个字符" minLength={8} maxLength={72} required autoComplete="new-password"/></label><button className="button primary wide" disabled={busy}>{busy?'提交中…':'重置密码'}</button></form><p className="auth-switch"><Link to="/login">返回登录</Link></p></div>;
}

function ChangePasswordPage(){
  const [current,setCurrent]=useState('');const [nextPassword,setNextPassword]=useState('');const [confirm,setConfirm]=useState('');const [busy,setBusy]=useState(false);const [done,setDone]=useState(false);const [error,setError]=useState('');
  const submit=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');if(nextPassword!==confirm){setError('两次输入的新密码不一致');setBusy(false);return}try{await post('/api/auth/change-password',{currentPassword:current,newPassword:nextPassword});setDone(true);setCurrent('');setNextPassword('');setConfirm('')}catch(e){setError(e instanceof Error?e.message:'修改失败')}finally{setBusy(false)}};
  return <div className="form-page compact-form"><div className="page-title"><span className="eyebrow">ACCOUNT SECURITY</span><h1>修改密码</h1><p>修改成功后，其他设备上的登录状态会自动失效，当前设备保持登录。</p></div>{done&&<div className="form-success"><CheckCircle2/>密码已修改，其他设备已退出登录。</div>}<form className="publish-form" onSubmit={submit}>{error&&<div className="form-error" role="alert">{error}</div>}<label>当前密码<input type="password" value={current} onChange={e=>setCurrent(e.target.value)} required autoComplete="current-password" minLength={8} maxLength={72}/></label><label>新密码<input type="password" value={nextPassword} onChange={e=>setNextPassword(e.target.value)} placeholder="至少 8 个字符" minLength={8} maxLength={72} required autoComplete="new-password"/></label><label>确认新密码<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="再次输入新密码" minLength={8} maxLength={72} required autoComplete="new-password"/></label><button className="button primary wide" disabled={busy}>{busy?'提交中…':'保存新密码'}</button></form><p className="auth-switch"><Link to="/profile">返回编辑资料</Link></p></div>;
}

export default function App(){return <Routes>
  <Route path="/login" element={<LoginPage/>}/>
  <Route path="/admin/*" element={<RequireAdmin><AdminApp/></RequireAdmin>}/>
  <Route path="*" element={<Shell><Routes>
    <Route path="/" element={<HomePage/>}/><Route path="/items/:id" element={<ItemDetailPage/>}/><Route path="/users/:id" element={<UserProfilePage/>}/><Route path="/safety" element={<SafetyPage/>}/><Route path="/reset-password" element={<ResetPasswordPage/>}/>
    <Route path="/publish" element={<RequireAuth><RequireCampus><PublishPage/></RequireCampus></RequireAuth>}/><Route path="/items/:id/edit" element={<RequireAuth><RequireCampus><PublishPage/></RequireCampus></RequireAuth>}/>
    <Route path="/messages" element={<RequireAuth><MessagesPage/></RequireAuth>}/><Route path="/messages/:id" element={<RequireAuth><ChatPage/></RequireAuth>}/><Route path="/orders" element={<RequireAuth><OrdersPage/></RequireAuth>}/>
    <Route path="/mine" element={<RequireAuth><MinePage/></RequireAuth>}/><Route path="/wallet" element={<RequireAuth><WalletPage/></RequireAuth>}/><Route path="/my-items" element={<RequireAuth><ItemCollection kind="mine"/></RequireAuth>}/><Route path="/favorites" element={<RequireAuth><ItemCollection kind="favorites"/></RequireAuth>}/><Route path="/profile" element={<RequireAuth><ProfilePage/></RequireAuth>}/><Route path="/profile/school-application" element={<RequireAuth><SchoolApplicationPage/></RequireAuth>}/><Route path="/password" element={<RequireAuth><ChangePasswordPage/></RequireAuth>}/><Route path="/feedback" element={<RequireAuth><FeedbackPage/></RequireAuth>}/>
    <Route path="*" element={<Navigate to="/" replace/>}/>
  </Routes></Shell>}/>
 </Routes>}
